#include "test_steps.h"
#include <cassert>
#include <iostream>
using namespace suitecut::runner;
namespace {
StepOwner Owner(uint64_t generation=1,uint64_t token=0,unsigned worker=1,int64_t pid=100){return{7,generation,token,9,generation,worker,pid};}
template<class F>void Reject(F fn){bool rejected=false;try{fn();}catch(const std::exception&){rejected=true;}assert(rejected);}
}
int main(){
 {TestSteps steps;const auto o=Owner();assert(steps.Open(o,1000,10));const auto a=steps.Begin(o,0,"\"outer\"",0,11);const auto b=steps.Begin(o,*a,"\"inner\"",0,12);assert(a&&b&&*a!=*b);assert(steps.Settle(o,*b,true,"\"\"",13));assert(steps.Settle(o,*a,true,"\"\"",14));assert(steps.Find(*b)->parent==*a&&steps.Find(*b)->depth==2);assert(steps.Find(*a)->ended==14);assert(steps.Close(o,15)&&steps.Retire(o)&&steps.Inspect().physical==0);}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);auto a=s.Begin(o,0,"\"caught child failure\"",0,1),b=s.Begin(o,*a,"\"actual thrown error\"",0,2);assert(s.Settle(o,*b,false,"\"original child error\"",3));assert(s.Find(*a)->status==StepStatus::Running);assert(s.Settle(o,*a,true,"\"\"",4));assert(s.Find(*a)->status==StepStatus::Passed&&s.Find(*b)->status==StepStatus::Failed);}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);auto a=s.Begin(o,0,"\"parallel grand\"",0,1),b=s.Begin(o,*a,"\"branch1\"",0,2),c=s.Begin(o,*a,"\"branch2\"",0,3),d=s.Begin(o,*b,"\"child1\"",0,4),e=s.Begin(o,*c,"\"child2\"",0,5);assert(s.Find(*d)->parent==*b&&s.Find(*e)->parent==*c);s.Settle(o,*d,true,"\"\"",6);s.Settle(o,*e,true,"\"\"",7);s.Settle(o,*c,true,"\"\"",8);s.Settle(o,*b,true,"\"\"",9);s.Settle(o,*a,true,"\"\"",10);}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);auto a=s.Begin(o,0,"\"timeout\"",10,1);s.Tick(11);assert(s.Find(*a)->status==StepStatus::TimedOut&&s.Find(*a)->ended==11);assert(s.Inspect().physical==1&&!s.Retire(o));assert(s.Close(o,12));assert(!s.Retire(o));assert(s.Settle(o,*a,false,"\"actual late rejection\"",15));assert(s.Find(*a)->status==StepStatus::TimedOut&&s.Find(*a)->receipt_error_json=="\"actual late rejection\""&&s.Find(*a)->received==15);assert(s.Retire(o));}
 {TestSteps s;const auto o=Owner();s.Open(o,20,0);auto a=s.Begin(o,0,"\"step cap\"",500,1);assert(s.Find(*a)->deadline==20);assert(s.Settle(o,*a,true,"\"\"",20));assert(s.Find(*a)->status==StepStatus::TimedOut&&s.Find(*a)->receipt_ok);}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);auto a=s.Begin(o,0,"\"parent\"",10,1),b=s.Begin(o,*a,"\"child\"",50,2);assert(s.Find(*b)->deadline==11);assert(!s.Begin(o,*a,"\"too late\"",0,11));assert(s.Find(*a)->status==StepStatus::TimedOut&&s.Find(*b)->status==StepStatus::TimedOut);}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);auto a=s.Begin(o,0,"\"settled parent\"",0,1),b=s.Begin(o,*a,"\"floating child\"",0,2);s.Settle(o,*a,true,"\"\"",3);assert(s.Find(*a)->status==StepStatus::Passed&&s.Find(*b)->status==StepStatus::Interrupted&&s.Inspect().physical==1);assert(!s.Begin(o,*a,"\"stale async ancestry\"",0,4));assert(s.Settle(o,*b,true,"\"\"",5));}
 {TestSteps s;const auto o=Owner(),other=Owner(1,1);s.Open(o,1000,0);s.Open(other,1000,0);auto a=s.Begin(o,0,"\"owned\"",0,1);assert(!s.Begin(other,*a,"\"cross callback parent\"",0,2));assert(!s.Settle(other,*a,true,"\"\"",3));assert(s.Inspect().physical==1);assert(!s.Settle(Owner(2),*a,true,"\"\"",4));assert(s.Settle(o,*a,true,"\"\"",5));assert(!s.Settle(o,*a,true,"\"\"",6));}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);for(size_t i=0;i<TestSteps::kPhysical;++i)assert(s.Begin(o,0,"\"bounded\"",0,1));assert(!s.Begin(o,0,"\"overflow\"",0,2));s.Close(o,3);assert(s.Inspect().physical==64);assert(!s.Begin(o,0,"\"canceled\"",0,4));assert(s.ConfirmedWorkerExit(1,100,5)&&s.Inspect().physical==0&&s.Retire(o));}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);uint64_t parent=0;for(size_t i=0;i<TestSteps::kDepth;++i)parent=*s.Begin(o,parent,"\"deep\"",0,1);assert(!s.Begin(o,parent,"\"depth overflow\"",0,2));s.Close(o,3);assert(s.TakeEvents().size()==64);assert(s.TakeEvents().empty());s.ConfirmedWorkerExit(1,100,4);}
 {TestSteps s;auto o=Owner();assert(!s.Open(o,0,0));assert(!s.Open(o,std::numeric_limits<double>::infinity(),0));assert(!s.Open(StepOwner{},100,0));Reject([&]{s.Open(o,100,NAN);});s.Open(o,1000,0);assert(!s.Open(o,1000,0));assert(!s.Begin(o,0,"not JSON",0,1));assert(!s.Begin(o,0,"\"too many units"+std::string(4097,'x')+"\"",0,2));assert(!s.Begin(o,0,"\"invalid timeout\"",120001,3));Reject([&]{s.Tick(2);});}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);auto a=s.Begin(o,0,"\"\\ud800\\u0000\"",0,1);assert(s.Find(*a)->title_json=="\"\\ud800\\u0000\"");assert(!s.Settle(o,*a,false,"not JSON",2));assert(!s.Settle(o,*a,true,"\"not an error\"",3));assert(s.Settle(o,*a,false,"\"\\udfff\\u0000\"",4));assert(s.Find(*a)->error_json=="\"\\udfff\\u0000\"");}
 {TestSteps s;const auto o=Owner();s.Open(o,20,0);auto a=s.Begin(o,0,"\"own deadline\"",10,1),b=s.Begin(o,*a,"\"child inherited cap\"",0,2);assert(s.UpdateOwnerDeadline(o,1000,3));assert(s.Find(*a)->deadline==11&&s.Find(*b)->deadline==11);assert(s.UpdateOwnerDeadline(o,5,4));s.Tick(5);assert(s.Find(*a)->status==StepStatus::TimedOut&&s.Find(*b)->status==StepStatus::TimedOut);assert(!s.UpdateOwnerDeadline(o,1000,6)&&s.Find(*a)->status==StepStatus::TimedOut);}
 {TestSteps s;const auto o=Owner();s.Open(o,1000,0);auto a=s.Begin(o,0,"\"worker exit\"",0,1);assert(!s.ConfirmedWorkerExit(2,100,2)&&!s.ConfirmedWorkerExit(1,101,3));assert(s.Inspect().physical==1);assert(s.ConfirmedWorkerExit(1,100,4));assert(s.Find(*a)->status==StepStatus::Interrupted&&s.Find(*a)->receipt==StepReceipt::WorkerExited);assert(!s.Settle(o,*a,true,"\"\"",5));assert(s.Retire(o));}
 {TestSteps s;auto first=Owner(),retry=Owner(2,0,2,101);s.Open(first,1000,0);auto a=s.Begin(first,0,"\"first attempt\"",0,1);s.Settle(first,*a,false,"\"first actual failure\"",2);s.Close(first,3);s.Retire(first);s.Open(retry,1000,4);auto b=s.Begin(retry,0,"\"retry\"",0,5);assert(*b>*a&&!s.Begin(retry,*a,"\"old attempt parent\"",0,6));assert(s.Settle(retry,*b,true,"\"\"",7));assert(s.Find(*a)->owner.attempt_generation==1&&s.Find(*b)->owner.attempt_generation==2);}
 {TestSteps s;const auto o=Owner();s.Open(o,1e12,0);size_t count=0;for(;;){auto id=s.Begin(o,0,"\"bounded cumulative ledger\"",0,1);if(!id)break;assert(s.Settle(o,*id,true,"\"\"",1));++count;}assert(count>64&&count<=TestSteps::kRecords&&s.Inspect().metadata_reserved<=TestSteps::kMetadata);assert(s.Inspect().physical==0);}
 std::cout<<"PASS16 native step ownership/deadline/receipt/ledger groups\n";
}
